"use client";

/**
 * Strike swap: one phrase in a sentence is struck through with a hand-drawn
 * line and fades back, then the replacement writes in after it.
 *
 * Written by Better Design. Painted from the theme prop, so the sentence takes
 * the product's ink and the strike and the new phrase take its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

const STRIKE_AT = 22;
const STRIKE_FRAMES = 16;
const FADE_AT = 42;
const WRITE_AT = 52;
/** Frames between two characters of the replacement. */
const CHAR_GAP = 1.4;
const CHAR_FRAMES = 10;

export interface StrikeSwapProps {
  /** The words before the struck phrase. */
  before?: string;
  /** The phrase that gets struck through. */
  struck?: string;
  /** The phrase that writes in after the struck one. */
  replacement?: string;
  /** The words after, punctuation included. They write in with the replacement. */
  after?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** Strike one phrase out by hand and write a better one in after it. */
export function StrikeSwap({
  before = "Launch films used to take",
  struck = "three weeks",
  replacement = "an afternoon",
  after = ".",
  theme: themeOverride,
  font,
}: StrikeSwapProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const enter = easings.out(interpolate(frame, [0, 18], [0, 1], clamp));
  const strike = easings.inOut(interpolate(frame, [STRIKE_AT, STRIKE_AT + STRIKE_FRAMES], [0, 1], clamp));
  const fade = easings.out(interpolate(frame, [FADE_AT, FADE_AT + 16], [0, 1], clamp));
  // Each word stays whole when the line wraps; each character keeps its place in the write-in order.
  // `i` is the character's place in the full tail, so it also says which part it belongs to.
  const tail = `${replacement}${after}`;
  const words: { chars: { ch: string; i: number }[] }[] = [{ chars: [] }];
  tail.split("").forEach((ch, i) => (ch === " " ? words.push({ chars: [] }) : words[words.length - 1].chars.push({ ch, i })));

  return (
    <AbsoluteFill style={{ background: theme.background, justifyContent: "center", paddingLeft: 180, paddingRight: 180, fontFamily: family }}>
      <div
        style={{
          fontSize: 104,
          fontWeight: 700,
          lineHeight: 1.18,
          letterSpacing: "-0.035em",
          color: theme.foreground,
          whiteSpace: "pre-wrap",
          opacity: enter,
          transform: `translateY(${(1 - enter) * 24}px)`,
        }}
      >
        {before}{" "}
        <span style={{ position: "relative", display: "inline-block", whiteSpace: "pre" }}>
          <span style={{ color: theme.foreground, opacity: 1 - 0.68 * fade }}>{struck}</span>
          <svg
            viewBox="0 0 100 20"
            preserveAspectRatio="none"
            style={{
              position: "absolute",
              left: "-4%",
              top: "44%",
              width: "108%",
              height: 34,
              overflow: "visible",
              opacity: 1 - 0.45 * fade,
              // The line is revealed left to right, like a pen pulled across the words.
              clipPath: `inset(-20px ${(1 - strike) * 100}% -20px -20px)`,
            }}
          >
            <path
              d="M 1 14 C 16 10, 30 15, 48 11.5 S 78 7, 99 8"
              fill="none"
              stroke={theme.primary}
              strokeWidth={9}
              strokeLinecap="round"
              vectorEffect="non-scaling-stroke"
            />
          </svg>
        </span>
        {words.map((word, w) => (
          <span key={w}>
            {" "}
            <span style={{ display: "inline-block", whiteSpace: "pre" }}>
              {word.chars.map(({ ch, i }) => {
                const t = easings.out(interpolate(frame, [WRITE_AT + i * CHAR_GAP, WRITE_AT + i * CHAR_GAP + CHAR_FRAMES], [0, 1], clamp));
                return (
                  <span
                    key={i}
                    style={{
                      display: "inline-block",
                      color: i < replacement.length ? theme.primary : theme.foreground,
                      opacity: t,
                      transform: `translateY(${(1 - t) * 0.22}em)`,
                      filter: `blur(${(1 - t) * 8}px)`,
                    }}
                  >
                    {ch}
                  </span>
                );
              })}
            </span>
          </span>
        ))}
      </div>
    </AbsoluteFill>
  );
}
